118→// ── Rule-based deterministic scoring ────────────────────────
119→
120→interface ExperienceBand {
121→  min_years: number;
122→  max_years: number;
123→  score: number;
124→  label: string;
125→}
126→
127→interface EducationLevel {
128→  level: string;
129→  score: number;
130→  aliases: string[];
131→}
