 53→// ── BT/ET PDF text extraction ───────────────────────────────
 54→function extractPdfText(bytes: Uint8Array): string {
 55→  const raw = new TextDecoder("latin1").decode(bytes);
 56→  const textChunks: string[] = [];
 57→  const btEtRegex = /BT\s([\s\S]*?)ET/g;
 58→  let block;
 59→  while ((block = btEtRegex.exec(raw)) !== null) {
 60→    const parenRegex = /\(([^)]*)\)/g;
 61→    let match;
 62→    while ((match = parenRegex.exec(block[1])) !== null) {
 63→      const decoded = match[1]
 64→        .replace(/\\n/g, "\n").replace(/\\r/g, "\r").replace(/\\t/g, "\t")
 65→        .replace(/\\\\/g, "\\").replace(/\\\(/g, "(").replace(/\\\)/g, ")");
 66→      if (decoded.trim()) textChunks.push(decoded);
 67→    }
 68→    const tjRegex = /\[([^\]]*)\]\s*TJ|(\([^)]*\))\s*Tj/g;
 69→    let tjMatch;
 70→    while ((tjMatch = tjRegex.exec(block[1])) !== null) {
 71→      const content = tjMatch[1] || tjMatch[2] || "";
 72→      const innerParen = /\(([^)]*)\)/g;
 73→      let ip;
 74→      while ((ip = innerParen.exec(content)) !== null) {
 75→        if (ip[1].trim()) textChunks.push(ip[1]);
 76→      }
 77→    }
 78→  }
 79→  return textChunks.join(" ").replace(/\s+/g, " ").trim().slice(0, 15000);
 80→}
