248→// ── Name validation ─────────────────────────────────────────
249→function isHexString(str: string): boolean {
250→  const cleaned = str.replace(/[\s\-_().]/g, '');
251→  if (cleaned.length < 4) return false;
252→  const hexChars = cleaned.replace(/[^a-fA-F0-9]/g, '').length;
253→  return hexChars / cleaned.length > 0.5;
254→}
255→
256→function isValidName(name: string | null | undefined): boolean {
257→  if (!name) return false;
258→  const lower = name.toLowerCase().trim();
259→  if (lower === "" || lower === "unknown candidate" || lower === "unknown" || lower === "n/a" || lower === "null") return false;
260→  if (isHexString(name)) return false;
261→  // Reject timestamps
262→  if (/^\d{10,}$/.test(name.trim())) return false;
263→  return true;
264→}
265→
266→function extractNameFromText(text: string): string | null {
267→  if (!text) return null;
268→  const lines = text.split('\n').slice(0, 5).map(l => l.trim()).filter(l => l.length > 0);
269→  for (const line of lines) {
270→    if (line.includes('@') || line.includes('http') || /^\d{3}/.test(line)) continue;
271→    if (/^(resume|curriculum|cv|objective|summary|profile|contact)/i.test(line)) continue;
272→    const words = line.split(/\s+/).filter(w => w.length > 1);
273→    if (words.length >= 2 && words.length <= 4 && words.every(w => /^[A-Z][a-zA-Z'-]+$/.test(w))) {
274→      return words.join(' ');
275→    }
276→  }
277→  return null;
278→}
279→
280→function nameFromFilename(filename: string): string | null {
281→  if (!filename) return null;
282→  let base = filename.replace(/\.[^.]+$/, "");
283→  base = base.replace(/^(resume|cv|Resume|CV)[_\-\s]*/i, "");
284→  base = base.replace(/[_\-\s]*(resume|cv|Resume|CV)$/i, "");
285→  base = base.replace(/[_\-]+/g, " ").trim();
286→  base = base.replace(/[a-f0-9]{8,}/gi, "").trim();
287→  base = base.replace(/\([^)]*\)/g, "").trim();
288→  base = base.replace(/^[\d\s\-_.]+/, "").replace(/[\d\s\-_.]+$/, "").trim();
289→  if (isHexString(base)) return null;
290→  if (base.length < 2 || !/[a-zA-Z]{2,}/.test(base)) return null;
291→  return base.split(/\s+/).map(w => w.charAt(0).toUpperCase() + w.slice(1).toLowerCase()).join(" ");
292→}
