294→// ── Generate embedding ──────────────────────────────────────
295→async function generateEmbedding(parsedJson: any, rawText: string): Promise<number[] | null> {
296→  try {
297→    const p = parsedJson || {};
298→    const parts: string[] = [];
299→    if (p.candidate_name) parts.push(p.candidate_name);
300→    if (p.skills_with_evidence) parts.push(`Skills: ${p.skills_with_evidence.map((s: any) => typeof s === 'string' ? s : s.skill || s.name || '').join(', ')}`);
301→    if (p.tools) parts.push(`Tools: ${p.tools.join(', ')}`);
302→    if (p.domain_experience) parts.push(`Domain: ${p.domain_experience}`);
303→    if (p.roles_with_dates) parts.push(`Roles: ${p.roles_with_dates.map((r: any) => `${r.title || r.role || ''} at ${r.company || ''}`).join('; ')}`);
304→    if (p.education) parts.push(`Education: ${p.education.map((e: any) => typeof e === 'string' ? e : `${e.degree || ''} ${e.institution || ''}`).join('; ')}`);
305→    const summary = parts.join('. ').slice(0, 4000) || rawText.slice(0, 4000);
306→
307→    const embResponse = await fetch("https://api.openai.com/v1/embeddings", {
308→      method: "POST",
309→      headers: { Authorization: `Bearer ${OPENAI_API_KEY}`, "Content-Type": "application/json" },
310→      body: JSON.stringify({ model: "text-embedding-3-small", input: [summary] }),
311→    });
312→    if (embResponse.ok) {
313→      const embData = await embResponse.json();
314→      return embData.data?.[0]?.embedding || null;
315→    }
316→    return null;
317→  } catch (err) {
318→    console.error("Embedding generation failed:", err);
319→    return null;
320→  }
321→}
